",
.\design\activity\card__7b158d24-318d-4081-934b-b9255a0672dc.json.d3b5041a-7021-4b54-9ae4-ad8fb362efdd.tmp:3955:          "output": "import { cardContext, fileContext, type ActionContext } from '../../data/action_context'
import { BUILTIN_CUSTOM_PROMPT, type ActionDefinition } from '../../data/action_types'
import type { ActionRunEvent } from '../../data/action_run_types'
import {
